INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Free Live Webinar: 🤖 Build Your AI Workforce Before Your Competitors Do', 'Chicago AI Magnet Community', 'Founders & Startups', 'AI is changing the way businesses operate—but the real opportunity isn''t simply using more AI tools. It''s building an **AI workforce** that', 'AI is changing the way businesses operate—but the real opportunity isn''t simply using more AI tools. It''s building an **AI workforce** that can support your sales, marketing, customer service, and operations. In this free 60-minute on-demand workshop, AI strategist **[Michelle Hummel](https://www.michellehummel.com/)** will show you how to identify where AI can make the biggest impact in your business and which AI employees you should consider building first. You''ll discover how to: ⚡ Identify More info: https://www.meetup.com/chicago-social-media-enthusiasts/events/vspcbvyjcpbqb/', '2026-11-12T13:00:00-06:00', 'Online event', 'Online event', 'Chicago', 'IL', '', 41.88, -87.62, 'Chicago AI Magnet Community', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/chicago-social-media-enthusiasts/events/vspcbvyjcpbqb/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
