INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('U.S. Visas & Immigration 101 for Startup Founders', 'Chicago Startup Founder 101', 'Founders & Startups', 'Building a company in the U.S. is hard enough. Doing it as a non-citizen founder means navigating an immigration system that was never', 'Building a company in the U.S. is hard enough. Doing it as a non-citizen founder means navigating an immigration system that was never designed with startups in mind. This 101 session breaks down the essentials in plain English. You''ll get a clear map of the visa paths open to founders, how they differ, and what each one actually asks of you when you''re the one building the company. We''ll also look at how milestones like fundraising and revenue shape your options, and the mistakes that quietly More info: https://www.meetup.com/chicago-startup-founder-101/events/316753081/', '2026-10-12T11:00:00-05:00', 'Online event', 'Online event', 'Chicago', 'IL', '', 41.88, -87.62, 'Chicago Startup Founder 101', 5, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/chicago-startup-founder-101/events/316753081/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('From Dreamer to Doer: Build the Founder Mindset', 'Chicago Startup Founder 101', 'Founders & Startups', 'Have you ever wondered why some people take the leap while others stay stuck? The difference isn''t luck, resources, or timing — it''s the', 'Have you ever wondered why some people take the leap while others stay stuck? The difference isn''t luck, resources, or timing — it''s the way founders think. Join Jonathan Greechan, Co-Founder & CEO of the Founder Institute, for a fascinating deep-dive into the psychology behind entrepreneurial action. In this live session, you''ll unpack the cognitive patterns that hold aspiring founders back and explore the mental frameworks that top entrepreneurs use to push through uncertainty. With practical More info: https://www.meetup.com/chicago-startup-founder-101/events/316598547/', '2026-10-13T11:00:00-05:00', 'Online event', 'Online event', 'Chicago', 'IL', '', 41.88, -87.62, 'Chicago Startup Founder 101', 4, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/chicago-startup-founder-101/events/316598547/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('How to Raise Money for Your AI Startup as a Solo Founder', 'Chicago Startup Founder 101', 'Founders & Startups', 'Solo founders now start a large share of new companies, but they still raise a much smaller share of venture money. Many investors learned', 'Solo founders now start a large share of new companies, but they still raise a much smaller share of venture money. Many investors learned to ask about the co-founder first. **In this session, you will hear how investors assess a solo AI founder in 2026, what makes up for a missing co-founder, and what traction they expect before the first check. Bring your questions for the live Q&A. [RSVP now!](https://fi.co/e/406098/meetup)** **❯ Guest Speakers include:** * Connor Sattely (CEO, Founder More info: https://www.meetup.com/chicago-startup-founder-101/events/316851888/', '2026-10-15T11:00:00-05:00', 'Online event', 'Online event', 'Chicago', 'IL', '', 41.88, -87.62, 'Chicago Startup Founder 101', 2, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/chicago-startup-founder-101/events/316851888/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
