INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('BOSS NETWORKING - business networking and strategy session', 'Chicago Tech Talk For Entrepreneurs', 'Founders & Startups', 'This isn''t just a club; it’s a high-level community for business strategists. We believe that the best plans are built together. Designed', 'This isn''t just a club; it’s a high-level community for business strategists. We believe that the best plans are built together. Designed for seasoned professionals, this is where you’ll find a peer group to help you refine your processes and master the blueprint for long-term growth. Join us to share ideas, gain fresh perspectives, and build your business with the collective intelligence of a supportive network. **The KPI Playbook:** Learn to develop and integrate key metrics that will align More info: https://www.meetup.com/chicago-tech-talk-for-entrepreneurs/events/316709010/', '2026-10-15T08:30:00-05:00', 'Online event', 'Online event', 'Chicago', 'IL', '', 41.89, -87.63, 'Chicago Tech Talk For Entrepreneurs', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/chicago-tech-talk-for-entrepreneurs/events/316709010/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Online Business Networking', 'Chicago Tech Talk For Entrepreneurs', 'Founders & Startups', 'You''ve probably asked the same questions we hear all the time: **Why is good networking so hard to find?** Why does it feel so', 'You''ve probably asked the same questions we hear all the time: **Why is good networking so hard to find?** Why does it feel so transactional? The truth is, most networking isn''t designed for you. Join this call to learn how CIBN is built from tip to toe to be member-serving. We believe that our success lives and dies in the success of our members—and we''ve designed everything around that philosophy. **Your Networking Story:** Share what''s worked for you (and what hasn''t) so we can understand More info: https://www.meetup.com/chicago-tech-talk-for-entrepreneurs/events/316710726/', '2026-10-15T11:00:00-05:00', 'Online event', 'Online event', 'Chicago', 'IL', '', 41.89, -87.63, 'Chicago Tech Talk For Entrepreneurs', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/chicago-tech-talk-for-entrepreneurs/events/316710726/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Smart Networking - Online Networking and Strategy Sharing', 'Chicago Tech Talk For Entrepreneurs', 'Founders & Startups', 'Stop guessing! At the SMART Networking Club, we believe that networking is a learnable skill, and our community is committed to setting you', 'Stop guessing! At the SMART Networking Club, we believe that networking is a learnable skill, and our community is committed to setting you up for success. We don''t just say "be a relationship builder"—we provide the proven, step-by-step process that makes this whole thing netWORK. This is the only club dedicated to the principles of our book, [SMART Networking: The $150,000 Method.](https://cibnconnect.com/betternetworking) **Key Highlights:** **Interactive Networking:** Attendees participated More info: https://www.meetup.com/chicago-tech-talk-for-entrepreneurs/events/316714625/', '2026-10-15T15:00:00-05:00', 'Online event', 'Online event', 'Chicago', 'IL', '', 41.89, -87.63, 'Chicago Tech Talk For Entrepreneurs', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/chicago-tech-talk-for-entrepreneurs/events/316714625/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
